using System.Net;
using System.Text;
using TeamsAgent.Core;
using TeamsAgent.Worker;
using Xunit;
namespace TeamsAgent.Tests;
public class AdapterTests
{
    [Fact] public async Task ForeignTenantGetsNoAiCall() { var t = Guid.NewGuid(); var called = false; var mod = new Moderator(t, (text, ct) => { called = true; return Task.FromResult("reply"); }); await Assert.ThrowsAsync<UnauthorizedAccessException>(() => mod.HandleAsync(Guid.NewGuid(), "bot", "message", "hello", [new("bot")], default)); Assert.False(called); }
    [Fact] public async Task LiteralAtTextIsNotMention() { var mod = new Moderator(Guid.Empty, (_, _) => throw new Exception()); Assert.Null(await mod.HandleAsync(Guid.Empty, "bot", "message", "@bot", [], default)); }
    [Fact] public async Task SystemEventDoesNotReply() { var t = Guid.NewGuid(); var mod = new Moderator(t, (_, _) => throw new Exception()); Assert.Null(await mod.HandleAsync(t, "bot", "conversationUpdate", "hello", [new("bot")], default)); }
    [Fact] public async Task DirectMentionUsesProvidedContext() { var t = Guid.NewGuid(); var mod = new Moderator(t, (text, ct) => Task.FromResult("Svar: " + text)); Assert.Equal("Svar: Hei", await mod.HandleAsync(t, "bot", "message", "Hei", [new("bot")], default)); }
    [Fact] public async Task AiDecisionsRequireTranscriptEvidence() { var h = new FakeHttp("{\"summary\":\"Budsjett\",\"decisions\":[{\"text\":\"Kjøp bil\",\"evidence\":\"Kjøp bil\"}],\"actions\":[]}"); var ai = new AzureAiClient(new(h), new("https://example.com"), "model", "key"); var k = new MeetingKey(Guid.NewGuid(), "m"); await Assert.ThrowsAsync<InvalidOperationException>(() => ai.GenerateAsync([new("s", k, TimeSpan.Zero, TimeSpan.FromSeconds(1), "ukjent taler", "Vi sjekker budsjett")], false, default)); }
    [Fact] public async Task AiReturnsGroundedDecision() { var h = new FakeHttp("{\"summary\":\"Budsjett\",\"decisions\":[{\"text\":\"sjekker budsjett\",\"evidence\":\"sjekker budsjett\"}],\"actions\":[]}"); var ai = new AzureAiClient(new(h), new("https://example.com"), "model", "key"); var k = new MeetingKey(Guid.NewGuid(), "m"); var m = await ai.GenerateAsync([new("s", k, TimeSpan.Zero, TimeSpan.FromSeconds(1), "ukjent taler", "Vi sjekker budsjett")], false, default); Assert.Single(m.Decisions); }
    [Fact] public async Task LongTranscriptIsProcessedInChunks() { var h = new FakeHttp("{\"summary\":\"Langt møte\",\"decisions\":[],\"actions\":[]}"); var ai = new AzureAiClient(new(h), new("https://example.com"), "model", "key"); var k = new MeetingKey(Guid.NewGuid(), "m"); var m = await ai.GenerateAsync([new("s", k, TimeSpan.Zero, TimeSpan.FromHours(2), "ukjent taler", new string('a', 80000))], false, default); Assert.NotEmpty(m.Summary); }
    [Fact] public async Task UnrelatedEvidenceCannotSupportInventedDecision() { var h = new FakeHttp("{\"summary\":\"Møte\",\"decisions\":[{\"text\":\"Kjøp bil\",\"evidence\":\"Hei\"}],\"actions\":[]}"); var ai = new AzureAiClient(new(h), new("https://example.com"), "model", "key"); var k = new MeetingKey(Guid.NewGuid(), "m"); await Assert.ThrowsAsync<InvalidOperationException>(() => ai.GenerateAsync([new("s", k, TimeSpan.Zero, TimeSpan.FromSeconds(1), "ukjent taler", "Hei")], false, default)); }
    [Fact] public async Task OwnerMentionElsewhereIsNotAssignment() { var h = new FakeHttp("{\"summary\":\"Møte\",\"decisions\":[],\"actions\":[{\"task\":\"Vi skal sjekke budsjett\",\"evidence\":\"Vi skal sjekke budsjett\",\"owner\":\"Kari\",\"deadline\":null}]}"); var ai = new AzureAiClient(new(h), new("https://example.com"), "model", "key"); var k = new MeetingKey(Guid.NewGuid(), "m"); var m = await ai.GenerateAsync([new("s", k, TimeSpan.Zero, TimeSpan.FromSeconds(1), "ukjent taler", "Kari er nevnt. Vi skal sjekke budsjett")], false, default); Assert.Equal("ikke oppgitt", m.Actions[0].Owner); }
    sealed class FakeHttp(string content) : HttpMessageHandler { protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage r, CancellationToken ct) => Task.FromResult(new HttpResponseMessage(HttpStatusCode.OK) { Content = new StringContent(System.Text.Json.JsonSerializer.Serialize(new { choices = new[] { new { message = new { content } } } }), Encoding.UTF8, "application/json") }); }
}
